@'
const fs = require("fs");
const path = require("path");
const root = "c:/git/semio/semio/fixtures";
const monolithPath = path.join(root, "metabolism.kit.semio.json");
const storeRoot = path.join(root, "stores", "metabolism");
const data = JSON.parse(fs.readFileSync(monolithPath, "utf8"));
const kit = data.wip?.initialKit ?? data.initialKit ?? data;
const ensure = (p) => fs.mkdirSync(p, { recursive: true });
const writeJson = (p, v) => {
  ensure(path.dirname(p));
  fs.writeFileSync(p, `${JSON.stringify(v, null, 4)}\n`);
};
const safe = (value) => String(value ?? "").trim().toLowerCase().replace(/\\/g, "backslash").replace(/\//g, "slash").replace(/&/g, " and ").replace(/\+/g, " plus ").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").replace(/-+/g, "-") || "item";
const typeFileName = (item, index) => {
  const iconBase = String(item.icon ?? "").split("/").pop()?.replace(/\.[^.]+$/, "") ?? "";
  if (iconBase.startsWith("capsule-with-balcony_")) return `${iconBase.replace("capsule-with-balcony_", "balcony_")}.capsule.type.semio.json`;
  if (iconBase.startsWith("capsule_")) return `${iconBase.replace("capsule_", "")}.capsule.type.semio.json`;
  if (iconBase.startsWith("tambour_")) return `${iconBase.replace("tambour_", "")}.tambour.type.semio.json`;
  const base = safe(item.name);
  return `${base}${index > 0 ? `.${index + 1}` : ""}.type.semio.json`;
};
const nonFlatDesigns = (kit.designs?.items ?? []).filter((d) => d.name !== "Flat");
const flatParents = nonFlatDesigns.map((d) => safe(d.name));
let flatIndex = 0;
const designFileName = (item, index) => {
  const base = safe(item.name);
  if (item.name === "Flat") {
    const parent = flatParents[flatIndex] ?? `design-${flatIndex + 1}`;
    flatIndex += 1;
    return `flat.${parent}.design.semio.json`;
  }
  return `${base}${index > 0 ? `.${index + 1}` : ""}.design.semio.json`;
};
const typesDir = path.join(storeRoot, "wip", "initialKit", "types");
const designsDir = path.join(storeRoot, "wip", "initialKit", "designs");
ensure(typesDir);
ensure(designsDir);
for (const entry of fs.readdirSync(typesDir)) fs.rmSync(path.join(typesDir, entry), { force: true, recursive: true });
for (const entry of fs.readdirSync(designsDir)) fs.rmSync(path.join(designsDir, entry), { force: true, recursive: true });
for (const entry of fs.readdirSync(path.join(storeRoot, "blobs"), { withFileTypes: false }).catch?.(() => []) ?? []) {}
const typeCounts = new Map();
for (const item of (kit.types?.items ?? [])) {
  const key = `${String(item.icon ?? "")}|${String(item.name ?? "")}`;
  const count = typeCounts.get(key) ?? 0;
  typeCounts.set(key, count + 1);
  writeJson(path.join(typesDir, typeFileName(item, count)), item);
}
const designCounts = new Map();
for (const item of (kit.designs?.items ?? [])) {
  const key = String(item.name ?? "");
  const count = designCounts.get(key) ?? 0;
  designCounts.set(key, count + 1);
  writeJson(path.join(designsDir, designFileName(item, count)), item);
}
writeJson(path.join(storeRoot, "wip", "initialKit", "kit.semio.json"), kit);
ensure(path.join(storeRoot, "wip", "alternatives"));
ensure(path.join(storeRoot, "wip", "checkpoints"));
const blobsDir = path.join(storeRoot, "blobs");
ensure(blobsDir);
for (const entry of fs.readdirSync(blobsDir)) fs.rmSync(path.join(blobsDir, entry), { force: true, recursive: true });
for (const blob of (data.blobs?.items ?? [])) {
  if (!blob || typeof blob !== "object") continue;
  const hash = blob.hash ?? blob.id ?? blob.name;
  const bytesBase64 = blob.bytesBase64 ?? blob.base64 ?? blob.bytes ?? null;
  const ext = String(blob.extension ?? blob.ext ?? blob.kind ?? "bin").replace(/^\./, "");
  if (!hash || !bytesBase64 || typeof bytesBase64 !== "string") continue;
  fs.writeFileSync(path.join(blobsDir, `${hash}.${ext}`), Buffer.from(bytesBase64, "base64"));
}
fs.rmSync(monolithPath, { force: true });
console.log(JSON.stringify({
  types: (kit.types?.items ?? []).length,
  designs: (kit.designs?.items ?? []).length,
  blobs: (data.blobs?.items ?? []).length,
  kitPath: path.join(storeRoot, "wip", "initialKit", "kit.semio.json")
}, null, 2));
